}, {"id": "435af587-f6ea-5030-a097-94ad466481c2", "profile_version": 1, "updated_at": "2026-10-15T08:58:03.138018+00:00"}, {"id": "bf6a7c6e-83e0-4d6d-8354-9a89ab679eb3", "profile_version": 2, "updated_at": "2026-11-11T12:56:55.882294+00:00"}]'::jsonb) AS x(id uuid,profile_version bigint,updated_at timestamptz);
DO $$BEGIN
 IF EXISTS(SELECT 1 FROM n25_profiles p LEFT JOIN public.teams t USING(id) WHERE t.id IS NULL OR row(t.profile_version,t.updated_at) IS DISTINCT FROM row(p.profile_version,p.updated_at)) THEN RAISE EXCEPTION 'Team profile baseline changed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.competition_seasons WHERE id='be008d39-f175-45c1-a232-2148d84b1cf9' AND lifecycle='active' AND publication_state='published') THEN RAISE EXCEPTION 'Edition state changed';END IF;
 IF (SELECT count(*) FROM n25_baseline)<>8 OR EXISTS(SELECT 1 FROM n25_baseline b LEFT JOIN public.fixtures f USING(id) WHERE row(b.competition_season_id,b.round_number,b.match_date,b.kickoff_time,b.court,b.home_team_id,b.away_team_id,b.schedule_version,b.updated_at,b.publication_state,b.schedule_status,b.stage) IS DISTINCT FROM row(f.competition_season_id,f.round_number,f.match_date,f.kickoff_time,f.court,f.home_team_id,f.away_team_id,f.schedule_version,f.updated_at,f.publication_state,f.schedule_status,f.stage) OR f.match_date<'2026-11-25') THEN RAISE EXCEPTION 'Fixture baseline changed or already applied';END IF;
 IF EXISTS(SELECT 1 FROM public.result_versions WHERE fixture_id IN(SELECT id FROM n25_baseline)) THEN RAISE EXCEPTION 'Result work exists';END IF;
 IF EXISTS(SELECT 1 FROM public.fixture_change_sets WHERE competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9' AND status IN('draft','pending_review')) THEN RAISE EXCEPTION 'Pending fixture plan';END IF;
END $$;
UPDATE public.fixtures f SET home_team_id=p.home_team_id,away_team_id=p.away_team_id FROM n25_target p WHERE p.id=f.id;
DO $$BEGIN
 IF EXISTS(SELECT 1 FROM n25_fixtures_before b FULL JOIN public.fixtures f USING(id) WHERE CASE WHEN b.id IN(SELECT id FROM n25_target) THEN
 (to_jsonb(b)-'home_team_id'-'away_team_id'-'schedule_version'-'updated_at') IS DISTINCT FROM (to_jsonb(f)-'home_team_id'-'away_team_id'-'schedule_version'-'updated_at') OR f.schedule_version<>b.schedule_version+1 OR NOT EXISTS(SELECT 1 FROM n25_target p WHERE p.id=f.id AND row(p.home_team_id,p.away_team_id)=row(f.home_team_id,f.away_team_id))
 ELSE to_jsonb(b) IS DISTINCT FROM to_jsonb(f) END) THEN RAISE EXCEPTION 'Unexpected fixture change';END IF;
 IF EXISTS(SELECT 1 FROM n25_results_before b FULL JOIN public.result_versions t USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(t)) THEN RAISE EXCEPTION 'Results changed';END IF;
 IF EXISTS(SELECT 1 FROM n25_teams_before b FULL JOIN public.teams t USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(t)) THEN RAISE EXCEPTION 'Teams changed';END IF;
 IF EXISTS(SELECT 1 FROM n25_notes_before b FULL JOIN public.team_fixture_notes t USING(team_id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(t)) THEN RAISE EXCEPTION 'Notes changed';END IF;
 IF EXISTS(SELECT 1 FROM n25_preferences_before b FULL JOIN public.team_kickoff_preferences t USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(t)) THEN RAISE EXCEPTION 'Preferences changed';END IF;
 IF EXISTS(SELECT 1 FROM n25_audit_before b LEFT JOIN public.admin_audit_log a USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(a)) THEN RAISE EXCEPTION 'Existing audit changed';END IF;
 IF (SELECT count(*)FROM public.fixtures WHERE competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9' AND publication_state='published' AND schedule_status='scheduled')<>240 THEN RAISE EXCEPTION 'Fixture total failed';END IF;
 IF EXISTS(SELECT 1 FROM public.fixtures WHERE competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9' AND publication_state='published' AND schedule_status='scheduled' GROUP BY least(home_team_id,away_team_id),greatest(home_team_id,away_team_id) HAVING count(*)<>2 OR count(DISTINCT home_team_id)<>2) THEN RAISE EXCEPTION 'Pair counts or home-away failed';END IF;
 IF EXISTS(SELECT round_number,team_id FROM(SELECT round_number,home_team_id team_id FROM public.fixtures WHERE competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9' AND publication_state='published' AND schedule_status='scheduled' UNION ALL SELECT round_number,away_team_id FROM public.fixtures WHERE competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9' AND publication_state='published' AND schedule_status='scheduled')x GROUP BY round_number,team_id HAVING count(*)<>1) THEN RAISE EXCEPTION 'Duplicate round appearance';END IF;
END $$;
SELECT txid_current() AS transaction_id,(SELECT count(*) FROM n25_target) AS changed_fixtures;
COMMIT;
